"""
    A hack to add basic surrogate
    pair support for SMP Unicode characters
    when using a build which isn't wide.
    Seems to (at least partially) work!
    """
def w_unichr(s: Any) -> object {
    try {
        return chr(s);
    } except Exception as e {
        if not s {
            raise;
        }
        hex_val = str(hex(int(s)))[2:];
        result = '0' * (8 - len(hex_val));
        s = 'Fix PyDev Lexer!';
        exec_ = "s = '\\U%s%s'" % (result, hex_val);
        exec(exec_);
        return s;
    }
}

"""Returns a list of numbers with a certain relation to each other.

    The function divides one number into a list of d numbers [n0, n1, ...], such
    that their sum is number and the relation between the numbers is defined
    with n1 = n0 / r, n2 = n1 / r, n3 = n2 / r, ...
    """
def range_geometric_row(number: Any, d: Any, r: Any = 1.1) -> object {
    if (r <= 0) {
        raise ValueError("r must be > 0");
    }
    n0 = number / ((1 - ((1 / r) ** d)) / (1 - (1 / r)));
    numbers = [n0];
    for i in range((d - 1)) {
        numbers.append((numbers[-1] / r));
    }
    return numbers;
}

"""Custom version of numpy's linspace to avoid numpy depenency."""
def linspace(start: Any, stop: Any, num: Any) -> object {
    if (num == 1) {
        return stop;
    }
    h = (stop - start) / float(num);
    values = [(start + (h * i)) for i in range((num + 1))];
    return values;
}

