}

"""Return the words-per-minute (WPM) of the TYPED string.

    Arguments:
        typed: an entered string
        elapsed: an amount of time in seconds

    >>> wpm('hello friend hello buddy hello', 15)
    24.0
    >>> wpm('0123456789',60)
    2.0
    """
def wpm(typed: str, elapsed: float) -> float {
    assert elapsed > 0, 'Elapsed time must be positive';
    return len(typed) / 5 / elapsed * 60;
}

"""Formats list of marked characters as a string."""
def format_match_string(marked_chr_list: list[tuple[str, bool]]) -> str {
    chr_list = [];
    mark_prev = False;
    for (chr, mark) in marked_chr_list {
        if mark != mark_prev {
            chr_list.append('(' if mark else ')');
        }
        chr_list.append(chr);
        mark_prev = mark;
    }
    if mark_prev {
        chr_list.append(')');
    }
    return ''.join(chr_list);
}

"""
    Applies the predicate to each item, taking the disjunction of the results.
    Will add d as a disjunct, and then finally will take that in
    conjunction with c. Returns the value.
    """
def build_mask[T](
    items: list[T],
    predicate: Callable[[T], int],
    d: int | None = None,
    c: int | None = None
) -> int | None {
    q: int | None = None;
    for i in items {
        if q is None {
            q = predicate(i);
        } else {
            q |= predicate(i);
        }
    }
    if d is not None {
        q = d | q;
    }
    if c is not None {
        q = c & q;
    }
    return q;
}

"""Calculate mean of a sequence; return empty if the sequence is empty."""
def mean(values: Iterable[float], empty: float = 0) -> float {
    (n, mean_val) = (0, 0.0);
    for value in values {
        n += 1;
        mean_val += (value - mean_val) / n;
    }
    return mean_val if n > 0 else empty;
}

"""
Arguments: {"joy": 1, "sadness": 0.8}, ["joy", "sadness", "trust"]
Returns: {"joy": 1, "sadness": 0.8, "trust": 0, "disgust": None, ...}
"""
def emotion_mapping(emotions: dict[str, float], dataset_emotions: list[str]) -> dict[str, float | None] {
    all_emotions = [
        "joy",
        "anger",
        "sadness",
        "disgust",
        "fear",
        "trust",
        "surprise",
        "love",
        "noemo",
        "confusion",
        "anticipation"
    ];
    d = {emotion: None for emotion in all_emotions} as dict[str, float | None];
    for emotion in all_emotions {
        if emotion in dataset_emotions {
            d[emotion] = emotions.get(emotion, 0);
        }
