    """
def time_format(seconds: int | float | str | None) -> str {
    if seconds is not None {
        seconds = int(seconds);
        d = seconds // (3600 * 24);
        h = seconds // 3600 % 24;
        m = seconds % 3600 // 60;
        s = seconds % 3600 % 60;
        if d > 0 {
            return '{:02d}D {:02d}H {:02d}m {:02d}s'.format(d, h, m, s);
        } elif h > 0 {
            return '{:02d}H {:02d}m {:02d}s'.format(h, m, s);
        } elif m > 0 {
            return '{:02d}m {:02d}s'.format(m, s);
        } elif s > 0 {
            return '{:02d}s'.format(s);
        }
    }
    return '-';
}

"""
Searches for first occurance of the provided target in the given array.
If target found then returns index of it, else None
Time Complexity = O(log n)
Space Complexity = O(1)
"""
def binary_search(arr: list[int], target: int) -> int | None {
    first = 0;
    last = len(arr) - 1;
    while first <= last {
        mid = (last + first) // 2;
        if arr[mid] == target {
            return mid;
        }
        if arr[mid] > target {
            last = mid - 1;
        }
        if arr[mid] < target {
            first = mid + 1;
        }
    }
    return None;
}

