    if "title" not in meta and "title_pattern" in meta {
        meta["title"] = meta["title_pattern"];
    }
    return meta;
}

"""return (g, x, y) such that a*x + b*y = g = gcd(a, b)"""
def pulverizer(a: int, b: int) -> tuple[int, int, int] {
    (x0, x1, y0, y1) = (0, 1, 1, 0);
    while a != 0 {
        (q, b, a) = (b // a, a, b % a);
        (y0, y1) = (y1, y0 - q * y1);
        (x0, x1) = (x1, x0 - q * x1);
    }
    return (b, x0, y0);
}

""" Exract word (space separated ) at current index"""
def extractWordInString(str_to_parse: str, index: int) -> str {
    i = index;
    while i != 0 and str_to_parse[i - 1] not in " \t\n&|" {
        i = i - 1;
    }
    left_part = str_to_parse[i:index];
    i = index;
    while i != len(str_to_parse) and str_to_parse[i] not in " \t\n&|" {
        i = i + 1;
    }
    right_part = str_to_parse[index:i];
    return left_part + right_part;
}

"""
    Compute the mean value of the entries in {iterable}
    """
def mean(iterable: Any) -> object {
    i = iter(iterable);
    count = 1;
    total = next(i);
    for item in i {
        count += 1;
        total += item;
    }
    return ((total * 1) / count);
}

"""Walks a data structure composed of nested lists/tuples/dicts, and
    creates a new (equivalent) structure in which the leaves of the data
    structure (i.e the non-list/tuple/dict data structures in the tree) have
    been mapped through f."""
def modify_leaves(f: Callable[[object], object], ds: object) -> object {
    if isinstance(ds, list) {
        return [modify_leaves(f, sds) for sds in ds];
    }
    if isinstance(ds, tuple) {
        return tuple(modify_leaves(f, sds) for sds in ds);
    }
    if isinstance(ds, dict) {
        return {k: modify_leaves(f, sds) for (k, sds) in ds.items()};
    }
    return f(ds);
}

"""Handle converter type "default"."""
def convert_default(*args: int | str | float | bool, **kwargs: int | str | float | bool) -> dict[str, str] {
    schema = {'type': 'string'};
    return schema;
}

"""Return pairs whose level-of-significance is at most 0.05."""
def identify_significant_pairs(list_pairs: list[list[str | float]]) -> list[list[str | float]] {
    return [x for x in list_pairs if x[2] <= 0.05];
}

"""Replaces Dictionary Values whenver bad_val is encountered with good_val."""
def replace_dict_value[T](d: dict[str, T], bad_val: T, good_val: T) -> dict[str, T] {
    for (k, v) in d.items() {
        if v == bad_val {
            d[k] = good_val;
        }
    }
    return d;
}

"""Converts a build target's name into the name of its associated crate.

    Crate names cannot contain certain characters, such as -, which are allowed
    in build target names. All illegal characters will be converted to
    underscores.

    This is a similar conversion as that which cargo does, taking a
    `Cargo.toml`'s `package.name` and canonicalizing it

    Note that targets can specify the `crate_name` attribute to customize their
    crate name; in situations where this is important, use the
    compute_crate_name() function instead.

    Args:
        name (str): The name of the target.

    Returns:
        str: The name of the crate for this target.
    """
def name_to_crate_name(name: str) -> str {
    for illegal in ("-", "/") {
        name = name.replace(illegal, "_");
    }
    return name;
}

"""Calculate precision at k."""
def pk(y_true: list[int], y_pred: list[int], k: int) -> float {
    y_pred = y_pred[:k];
    common_values = set(y_pred).intersection(set(y_true));
    return len(common_values) / len(y_pred);
}

""" Obtained from: https://github.com/doukremt/distance/blob/master/distance/_simpledists.py
        on Sept 8 2015

    Compute the Jaccard distance between the two sequences `seq1` and `seq2`.
    They should contain hashable items.
    The return value is a float between 0 and 1, where 0 means equal, and 1 totally different.
    """
def jaccard(seq1: list[str | int], seq2: list[str | int]) -> float {
    (set1, set2) = (set(seq1), set(seq2));
    return 1 - len(set1 & set2) / float(len(set1 | set2));
}

"""Return the sensitivity based on the confusion matrix values."""
def calculateSensitivity(tn: int, fp: int, fn: int, tp: int) -> float {
    return tp / (tp + fn);
}

"""Return 10^n: 10^n > num; 10^(n-1) <= num."""
def nifty_power_of_ten(num: int) -> int {
    result = 10;
    while result <= num {
        result *= 10;
    }
    return result;
}

""" Find valid passwords with min and max count """
def validate_passwords(password_list: Any) -> object {
    count = 0;
    for password in password_list {
        if (
            password["min"]
            <= password["password"].count(password["char"])
            <= password["max"]
        ) {
            count += 1;
        }
    }
    return count;
}

"""Private function to check whether all elements of list_to_check are equal."""
def _all_elements_equal(list_to_check: list[str]) -> bool {
    if len(list_to_check) == 1 {
        return True;
    }
    return all(list_to_check[i] == list_to_check[i + 1] for i in range(len(list_to_check) - 1));
}

"""
    Two period of data change in pecentage (without %)
    """
def divided_and_show_pct(a: Any, b: Any) -> object {
    return round(((float(a) / float(b)) * 100), 2);
}

"""Convert string to float, but also handles None and 'null'."""
def to_float(val: str | int | float | None) -> float | None {
    if val is None {
        return None;
    }
    if str(val) == "null" {
        return None;
    }
    return float(val);
}

"""Newton's method with poor initial guess of n."""
def newton(n: float, error: float) -> float {
    x = n;
    while abs(x ** 2 - n) > error {
        x = x - (x ** 2 - n) / (2 * x);
    }
    return x;
}

"""Get gaps merged across channels/streams
    Parameters
    ----------
    gaps: dictionary
        contains channel/gap array pairs

    Returns
    -------
    array_like
        an array of startime/endtime arrays representing gaps.

    Notes
    -----
    Takes an dictionary of gaps, and merges those gaps across channels,
        returning an array of the merged gaps.
    """
def get_merged_gaps(gaps: dict[str, list[list[float]]]) -> list[list[float]] {
    merged_gaps = [];
    for key in gaps {
        merged_gaps.extend(gaps[key]);
    }
    sorted_gaps: list[list[float]] = sorted(merged_gaps, key=lambda (gap: list[float]) { gap[0]; });
    merged_gaps = [];
    merged_gap: list[float] | None = None;
    for gap in sorted_gaps {
        if merged_gap is None {
            merged_gap = gap;
        } elif gap[0] > merged_gap[2] {
            merged_gaps.append(merged_gap as list[float]);
            merged_gap = gap;
        } elif gap[0] <= merged_gap[2] {
            if gap[1] > merged_gap[1] {
                merged_gap[1] = gap[1];
                merged_gap[2] = gap[2];
            }
        }
    }
    if merged_gap is not None {
        merged_gaps.append(merged_gap);
    }
    return merged_gaps;
}
